use anyhow::{Context, Result};
use std::env;
use std::sync::Arc;
use vim_rs::core::client::{Client, ClientBuilder};

#[tokio::main]
async fn main() -> Result<()> {
    let vc_server = env::var("VIM_SERVER")
        .with_context(|| "VIM_SERVER env var not set")?;
    let username = env::var("VIM_USERNAME")
        .with_context(|| "VIM_USERNAME env var not set")?;
    let pwd = env::var("VIM_PASSWORD")
        .with_context(|| "VIM_PASSWORD env var not set")?;

    let client = ClientBuilder::new(vc_server.as_str())
        .insecure(true)  // Accept self-signed certs
        .basic_authn(username.as_str(), pwd.as_str())
        .app_details("my-app", "1.0.0")
        .build()
        .await?;

    println!("Connected to {}", client.service_content().about.full_name);
    Ok(())
}

use anyhow::Result;
use log::info;
use vim_macros::vim_retrievable;
use vim_rs::core::pc_retrieve::ObjectRetriever;
use vim_rs::core::client::Client;
use std::sync::Arc;

// Define a struct mapped to VirtualMachine managed object
vim_retrievable!(
    struct VmInfo: VirtualMachine {
        name = "name",
        power_state = "runtime.power_state",
        cpu_count = "config.hardware.num_cpu",
        memory_mb = "config.hardware.memory_mb",
        guest_os = "config.guest_full_name",
    }
);

#[tokio::main]
async fn main() -> Result<()> {
    env_logger::init();
    let client = connect_to_vsphere().await?; // Use connection pattern

    let retriever = ObjectRetriever::new(client.clone())?;

    // Retrieve all VMs from root folder
    let vms: Vec<VmInfo> = retriever
        .retrieve_objects_from_container(&client.service_content().root_folder)
        .await?;

    for vm in vms {
        info!("VM: {} - CPUs: {:?}, RAM: {:?}MB, Power: {:?}",
            vm.name, vm.cpu_count, vm.memory_mb, vm.power_state);
    }

    Ok(())
}

use anyhow::Result;
use vim_rs::mo::{ContainerView, PropertyCollector, ViewManager};
use vim_rs::types::structs::{PropertyFilterSpec, ObjectSpec, TraversalSpec, PropertySpec, RetrieveOptions};
use vim_rs::types::enums::MoTypesEnum;

#[tokio::main]
async fn main() -> Result<()> {
    let client = connect_to_vsphere().await?;
    let content = client.service_content();

    // Create a container view for VMs
    let view_manager = ViewManager::new(
        client.clone(),
        content.view_manager.clone().unwrap().value.as_str()
    );

    let view_moref = view_manager
        .create_container_view(
            &content.root_folder,
            Some(&[Into::<&str>::into(MoTypesEnum::VirtualMachine).to_string()]),
            true
        )
        .await?;

    // Build property filter spec
    let spec_set = vec![PropertyFilterSpec {
        object_set: vec![ObjectSpec {
            obj: view_moref.clone(),
            skip: Some(false),
            select_set: Some(vec![Box::new(TraversalSpec {
                name: Some("traverseEntities".to_string()),
                r#type: Into::<&str>::into(MoTypesEnum::ContainerView).to_string(),
                path: "view".to_string(),
                skip: Some(false),
                select_set: None,
            })]),
        }],
        prop_set: vec![PropertySpec {
            all: Some(false),
            path_set: Some(vec!["name".to_string()]),
            r#type: Into::<&str>::into(MoTypesEnum::VirtualMachine).to_string(),
        }],
        report_missing_objects_in_results: Some(true),
    }];

    let property_collector = PropertyCollector::new(client.clone(), &content.property_collector.value);
    let result = property_collector.retrieve_properties_ex(&spec_set, &RetrieveOptions { max_objects: Some(100) }).await?;

    // Process results...
    Ok(())
}

use log::info;
use std::time::Instant;
use vim_macros::vim_updatable;
use vim_rs::core::pc_cache::{CacheManager, ObjectCache, ObjectCacheListener};

// Define updatable struct (supports change tracking)
vim_updatable!(
    struct VmDetails: VirtualMachine {
        name = "name",
        power_state = "runtime.power_state",
    }
);

// Implement listener for change notifications
struct ChangeListener {}

impl ObjectCacheListener<VmDetails> for ChangeListener {
    fn on_new(&mut self, obj: &VmDetails) {
        info!("New VM created: {} - {:?}", obj.name, obj.power_state);
    }

    fn on_update(&mut self, obj: &VmDetails) {
        info!("VM updated: {} - {:?}", obj.name, obj.power_state);
    }

    fn on_remove(&mut self, obj: VmDetails) {
        info!("VM removed: {}", obj.name);
    }
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let client = connect_to_vsphere().await?;

    let cache = ObjectCache::new_with_listener(Box::new(ChangeListener {}));
    let mut manager = CacheManager::new(client.clone())?;
    let mut monitor = manager.create_monitor()?;

    // Start monitoring VMs in root folder
    manager.add_container_cache(Box::new(cache), &client.service_content().root_folder).await?;

    // Poll for updates
    loop {
        monitor.poll_for_updates().await?;
        tokio::time::sleep(tokio::time::Duration::from_secs(5)).await;
    }
}

use anyhow::Result;
use chrono::{Duration as ChronoDuration, Utc};
use log::info;
use vim_rs::mo::EventManager;
use vim_rs::types::structs::{Event, EventFilterSpec, EventFilterSpecByTime};

#[tokio::main]
async fn main() -> Result<()> {
    let client = connect_to_vsphere().await?;
    let event_manager = EventManager::new(
        client.clone(),
        client.service_content().event_manager.as_ref().unwrap().value.as_str()
    );

    // Get events from last 30 minutes
    let now = Utc::now();
    let past = now - ChronoDuration::minutes(30);

    let filter = EventFilterSpec {
        time: Some(Box::new(EventFilterSpecByTime {
            begin_time: Some(past),
            end_time: Some(now),
        })),
        ..Default::default()
    };

    let collector = event_manager.create_collector_for_events(&filter).await?;
    let events: Vec<Event> = collector.read_next_events(100).await?;

    for event in events {
        info!("Event: {} at {}", 
            event.extra_fields_.get("eventTypeId").and_then(|v| v.as_str()).unwrap_or("unknown"),
            event.created_time
        );
    }

    Ok(())
}

