use log::info;
use vim_rs::core::RootObjects;

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let client = connect_to_vsphere().await?;
    let root_objects = RootObjects::new(client.clone());

    // VIM (Virtual Infrastructure Management)
    let vim_about = root_objects.vim_service_instance().content().await?.about;
    info!("vCenter version: {}", vim_about.version);

    // EAM (ESX Agent Manager)
    let agencies = root_objects.esx_agent_manager().agency().await?;
    info!("EAM agencies: {:?}", agencies);

    // PBM (Policy Based Management / Storage Policies)
    let pbm_about = root_objects.pbm_service_instance().content().await?.about_info;
    info!("PBM version: {}", pbm_about.version);

    // VSLM (vSphere Storage for Kubernetes / First Class Disks)
    let vslm_about = root_objects.vslm_service_instance().content().await?.about_info;
    info!("VSLM API version: {}", vslm_about.api_version);

    // SMS (Storage Monitoring Service)
    let sms_about = root_objects.sms_service_instance().query_about_info().await?;
    info!("SMS VASA version: {:?}", sms_about.vasa_api_version);

    Ok(())
}
